{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@forget2save/mytui",
  "version": "0.13.0",
  "description": "Workspace config manager, session board, complete trajectory viewer, notifications, and tool timing for opencode TUI",
  "type": "module",
  "license": "MIT",
  "exports": {
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "skill/SKILL.md",
    "README.md"
  ],
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "test": "npm run build && bun --conditions=browser test",
    "prepublishOnly": "npm test"
  },
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "opencode": ">=1.16.0"
  },
  "peerDependencies": {
    "@opentui/core": "0.4.5",
    "@opentui/solid": "0.4.5",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.16.0",
    "@opencode-ai/sdk": "1.16.0",
    "@opentui/core": "0.4.5",
    "@opentui/solid": "0.4.5",
    "@types/node": "^24.3.0",
    "esbuild-plugin-solid": "^0.6.0",
    "solid-js": "1.9.12",
    "tsup": "^8.5.0",
    "typescript": "^5.9.2"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "theme",
    "session-board",
    "trajectory",
    "conversation-trace",
    "workspace",
    "opencode-config",
    "jsonc",
    "mcp",
    "skills",
    "ascii-art",
    "rainbow"
  ],
  "dependencies": {
    "jsonc-parser": "3.3.1"
  }
}
